import React, { useState, useEffect, useCallback, useRef } from 'react';
import type { Project } from '../types';
import LazyImage from './LazyImage';
import { createFocusTrap, announceToScreenReader, createLiveRegion, updateLiveRegion } from '../utils/focusManagement';
import { getAutoResizedThumbnails } from '../utils/imageAutoResize';
import './ProjectModal.css';

interface ProjectModalProps {
  project: Project;
  onClose: () => void;
  relatedProjects: Project[];
  onProjectSelect?: (project: Project) => void;
}

const ProjectModal: React.FC<ProjectModalProps> = ({
  project,
  onClose,
  relatedProjects,
  onProjectSelect
}) => {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const modalRef = useRef<HTMLDivElement>(null);
  const focusTrapRef = useRef<any>(null);
  const previouslyFocusedElementRef = useRef<HTMLElement | null>(null);

  // Handle keyboard navigation
  const handleKeyDown = useCallback((event: KeyboardEvent) => {
    switch (event.key) {
      case 'Escape':
        onClose();
        break;
      case 'ArrowLeft':
        if (project.imageUrls.length > 1) {
          setCurrentImageIndex(prev => 
            prev === 0 ? project.imageUrls.length - 1 : prev - 1
          );
        }
        break;
      case 'ArrowRight':
        if (project.imageUrls.length > 1) {
          setCurrentImageIndex(prev => 
            prev === project.imageUrls.length - 1 ? 0 : prev + 1
          );
        }
        break;
    }
  }, [onClose, project.imageUrls.length]);

  // Set up focus management and accessibility
  useEffect(() => {
    // Store previously focused element
    previouslyFocusedElementRef.current = document.activeElement as HTMLElement;
    
    // Create live region for announcements
    createLiveRegion('modal-announcements', 'polite');
    
    // Set up focus trap
    if (modalRef.current) {
      focusTrapRef.current = createFocusTrap(modalRef.current);
      focusTrapRef.current.activate();
    }
    
    // Announce modal opening
    announceToScreenReader(`Project details for ${project.title} opened`);
    
    document.addEventListener('keydown', handleKeyDown);
    document.body.style.overflow = 'hidden';
    
    return () => {
      // Clean up focus trap
      if (focusTrapRef.current) {
        focusTrapRef.current.deactivate();
      }
      
      document.removeEventListener('keydown', handleKeyDown);
      document.body.style.overflow = 'unset';
      
      // Announce modal closing
      announceToScreenReader('Project details closed');
    };
  }, [handleKeyDown, project.title]);

  const handleOverlayClick = (event: React.MouseEvent) => {
    if (event.target === event.currentTarget) {
      onClose();
    }
  };

  const handleImageLoad = () => {
    // setIsImageLoading(false); // This line was removed
  };

  const handleImageError = () => {
    // setIsImageLoading(false); // This line was removed
  };

  const navigateImage = (direction: 'prev' | 'next') => {
    if (project.imageUrls.length <= 1) return;
    
    // setIsImageLoading(true); // This line was removed
    let newIndex: number;
    
    if (direction === 'prev') {
      newIndex = currentImageIndex === 0 ? project.imageUrls.length - 1 : currentImageIndex - 1;
      setCurrentImageIndex(newIndex);
    } else {
      newIndex = currentImageIndex === project.imageUrls.length - 1 ? 0 : currentImageIndex + 1;
      setCurrentImageIndex(newIndex);
    }
    
    // Announce image change to screen readers
    updateLiveRegion('modal-announcements', `Image ${newIndex + 1} of ${project.imageUrls.length}`);
  };

  const handleRelatedProjectClick = (relatedProject: Project) => {
    if (onProjectSelect) {
      onProjectSelect(relatedProject);
    }
  };

  return (
    <div 
      className="project-modal-overlay"
      onClick={handleOverlayClick}
      role="dialog"
      aria-modal="true"
      aria-labelledby="modal-title"
      aria-describedby="modal-description"
    >
      <div className="project-modal" ref={modalRef}>
        <button
          className="project-modal__close"
          onClick={onClose}
          aria-label="Close project details"
          type="button"
        >
          ×
        </button>

        <div className="project-modal__content">
          {/* Image Gallery Section */}
          <div className="project-modal__gallery">
            <div className="project-modal__image-container">
              <LazyImage
                src={project.imageUrls[currentImageIndex] || getAutoResizedThumbnails(project.thumbnailUrl).xlarge}
                alt={`${project.title} - Image ${currentImageIndex + 1}`}
                className="project-modal__image"
                onLoad={handleImageLoad}
                onError={handleImageError}
                sizes="(max-width: 768px) 100vw, (max-width: 1024px) 80vw, 60vw"
                aspectRatio="16 / 9"
                priority={true} // Modal images should load with priority
              />
              
              {project.imageUrls.length > 1 && (
                <>
                  <button
                    className="project-modal__nav project-modal__nav--prev"
                    onClick={() => navigateImage('prev')}
                    aria-label="Previous image"
                    type="button"
                  >
                    ‹
                  </button>
                  <button
                    className="project-modal__nav project-modal__nav--next"
                    onClick={() => navigateImage('next')}
                    aria-label="Next image"
                    type="button"
                  >
                    ›
                  </button>
                </>
              )}
            </div>
            
            {project.imageUrls.length > 1 && (
              <div className="project-modal__image-indicators">
                {project.imageUrls.map((_, index) => (
                  <button
                    key={index}
                    className={`project-modal__indicator ${
                      index === currentImageIndex ? 'project-modal__indicator--active' : ''
                    }`}
                    onClick={() => {
                      // setIsImageLoading(true); // This line was removed
                      setCurrentImageIndex(index);
                    }}
                    aria-label={`Go to image ${index + 1}`}
                    type="button"
                  />
                ))}
              </div>
            )}
          </div>

          {/* Project Details Section */}
          <div className="project-modal__details">
            <div className="project-modal__header">
              <h1 id="modal-title" className="project-modal__title">
                {project.title}
              </h1>
              {project.featured && (
                <span className="project-modal__featured-badge" aria-label="Featured project">
                  Featured
                </span>
              )}
            </div>

            <div className="project-modal__meta">
              <span className="project-modal__category">
                {project.category.name}
              </span>
              <span className={`project-modal__status project-modal__status--${project.status}`}>
                {project.status.charAt(0).toUpperCase() + project.status.slice(1).replace('-', ' ')}
              </span>
            </div>

            <p id="modal-description" className="project-modal__description">
              {project.longDescription || project.description}
            </p>

            {/* Technology Stack */}
            <div className="project-modal__section">
              <h2 className="project-modal__section-title">Technology Stack</h2>
              <div className="project-modal__technologies">
                {project.technologies.map((tech) => (
                  <div
                    key={tech.id}
                    className="project-modal__tech-badge"
                    style={{ backgroundColor: tech.color }}
                  >
                    <span className="project-modal__tech-icon" aria-hidden="true">
                      {tech.icon}
                    </span>
                    <span className="project-modal__tech-name">{tech.name}</span>
                    <span className="project-modal__tech-category">
                      {tech.category}
                    </span>
                  </div>
                ))}
              </div>
            </div>

            {/* Project Links */}
            {(project.demoUrl || project.sourceUrl) && (
              <div className="project-modal__section">
                <h2 className="project-modal__section-title">Project Links</h2>
                <div className="project-modal__links">
                  {project.demoUrl && (
                    <a
                      href={project.demoUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="project-modal__link project-modal__link--demo"
                    >
                      <span className="project-modal__link-icon" aria-hidden="true">🚀</span>
                      View Live Demo
                      <span className="project-modal__link-external" aria-hidden="true">↗</span>
                    </a>
                  )}
                  {project.sourceUrl && (
                    <a
                      href={project.sourceUrl}
                      target="_blank"
                      rel="noopener noreferrer"
                      className="project-modal__link project-modal__link--source"
                    >
                      <span className="project-modal__link-icon" aria-hidden="true">📁</span>
                      View Source Code
                      <span className="project-modal__link-external" aria-hidden="true">↗</span>
                    </a>
                  )}
                </div>
              </div>
            )}

            {/* Related Projects */}
            {relatedProjects.length > 0 && (
              <div className="project-modal__section">
                <h2 className="project-modal__section-title">Related Projects</h2>
                <div className="project-modal__related-projects">
                  {relatedProjects.slice(0, 3).map((relatedProject) => (
                    <button
                      key={relatedProject.id}
                      className="project-modal__related-project"
                      onClick={() => handleRelatedProjectClick(relatedProject)}
                      type="button"
                    >
                      <div className="project-modal__related-image-container">
                        <LazyImage
                          src={getAutoResizedThumbnails(relatedProject.thumbnailUrl).small}
                          alt={relatedProject.title}
                          className="project-modal__related-image"
                          sizes="(max-width: 768px) 100px, 120px"
                          aspectRatio="16 / 10"
                        />
                      </div>
                      <div className="project-modal__related-content">
                        <h3 className="project-modal__related-title">
                          {relatedProject.title}
                        </h3>
                        <p className="project-modal__related-description">
                          {relatedProject.description}
                        </p>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default ProjectModal;