import React from 'react';
import LazyImage from './LazyImage';
import { announceToScreenReader } from '../utils/focusManagement';
import './ContactCard.css';

interface ContactCardProps {
  onContactClick: () => void;
}

const ContactCard: React.FC<ContactCardProps> = ({ onContactClick }) => {
  const handleClick = () => {
    onContactClick();
    announceToScreenReader('Opening contact information', 'assertive');
  };

  const handleKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      onContactClick();
      announceToScreenReader('Opening contact information', 'assertive');
    }
  };

  return (
    <div
      className="contact-card"
      onClick={handleClick}
      onKeyDown={handleKeyDown}
      tabIndex={0}
      role="button"
      aria-label="Get in touch with Craig"
    >
      <div className="contact-card__card">
        <div className="contact-card__image-container">
          <LazyImage
            src="https://i.ibb.co/1tVxdbKJ/1-a-Io5-AI-4-FJyu9b-Brr-Myjd-A.png"
            alt="Contact Craig Ng"
            className="contact-card__image"
            sizes="(max-width: 768px) 280px, (max-width: 1024px) 320px, 400px"
            aspectRatio="16 / 9"
          />

          <div className="contact-card__overlay">
            <div className="contact-card__content">
              <h3 className="contact-card__title">Get in Touch</h3>


              <div className="contact-card__badges">
                <span className="contact-card__badge">
                  <span className="contact-card__badge-icon">💼</span>
                  <span>LinkedIn</span>
                </span>
                <span className="contact-card__badge">
                  <span className="contact-card__badge-icon">📧</span>
                  <span>Email</span>
                </span>
              </div>

              <div className="contact-card__actions">
                <button className="contact-card__contact-btn" aria-label="Contact Craig">
                  <svg viewBox="0 0 24 24" fill="currentColor">
                    <path d="M20 4H4c-1.1 0-1.99.9-1.99 2L2 18c0 1.1.9 2 2 2h16c1.1 0 2-.9 2-2V6c0-1.1-.9-2-2-2zm0 4l-8 5-8-5V6l8 5 8-5v2z" />
                  </svg>
                  Contact
                </button>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ContactCard;