import React, { useState, useRef, useEffect } from 'react';
import { generateResponsiveSrcSet, createPlaceholderSVG } from '../utils/imageOptimization';
import { generateAutoResizeSrcSet, generateAutoResizeSizes } from '../utils/imageAutoResize';
import './LazyImage.css';

interface LazyImageProps {
  src: string;
  alt: string;
  className?: string;
  placeholder?: string;
  sizes?: string;
  srcSet?: string;
  onLoad?: () => void;
  onError?: () => void;
  aspectRatio?: string;
  priority?: boolean;
  quality?: number;
}

const LazyImage: React.FC<LazyImageProps> = ({
  src,
  alt,
  className = '',
  placeholder,
  sizes,
  srcSet,
  onLoad,
  onError,
  aspectRatio,
  priority = false,
}) => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isError, setIsError] = useState(false);
  const [isInView, setIsInView] = useState(priority);
  const imgRef = useRef<HTMLImageElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // Intersection Observer for lazy loading
  useEffect(() => {
    if (priority || isInView) return;

    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          if (entry.isIntersecting) {
            setIsInView(true);
            observer.disconnect();
          }
        });
      },
      {
        rootMargin: '50px', // Start loading 50px before the image comes into view
        threshold: 0.1
      }
    );

    if (containerRef.current) {
      observer.observe(containerRef.current);
    }

    return () => observer.disconnect();
  }, [priority, isInView]);

  const handleLoad = () => {
    setIsLoaded(true);
    onLoad?.();
  };

  const handleError = () => {
    setIsError(true);
    onError?.();
  };

  // Resolve src to respect Vite base URL on subpath deployments (e.g., GitHub Pages)
  const resolvedSrc = src && src.startsWith('/')
    ? `${import.meta.env.BASE_URL}${src.slice(1)}`
    : src;

  // Generate responsive srcSet if not provided
  const generateSrcSet = (baseSrc: string): string => {
    if (srcSet) return srcSet;
    
    // Use auto-resize utility for better optimization
    try {
      return generateAutoResizeSrcSet(baseSrc);
    } catch (error) {
      console.warn('Auto-resize failed, falling back to standard optimization:', error);
      return generateResponsiveSrcSet(baseSrc);
    }
  };

  // Generate default sizes if not provided
  const defaultSizes = sizes || generateAutoResizeSizes();

  // Create placeholder image (low quality placeholder)
  const createPlaceholder = (): string => {
    if (placeholder) return placeholder;
    
    // Use the image optimization utility
    return createPlaceholderSVG(400, 300, '#2a2a2a', '#1a1a1a');
  };

  return (
    <div 
      ref={containerRef}
      className={`lazy-image ${className}`}
      style={{ aspectRatio }}
    >
      {/* Placeholder/Loading state */}
      {!isLoaded && !isError && (
        <div className="lazy-image__placeholder">
          <img
            src={createPlaceholder()}
            alt=""
            className="lazy-image__placeholder-img"
            aria-hidden="true"
          />
          <div className="lazy-image__loading-spinner">
            <div className="lazy-image__spinner"></div>
          </div>
        </div>
      )}

      {/* Main image */}
      {isInView && !isError && (
        <img
          ref={imgRef}
          src={resolvedSrc}
          srcSet={generateSrcSet(resolvedSrc)}
          sizes={defaultSizes}
          alt={alt}
          className={`lazy-image__img ${isLoaded ? 'lazy-image__img--loaded' : ''}`}
          onLoad={handleLoad}
          onError={handleError}
          loading={priority ? 'eager' : 'lazy'}
          decoding="async"
        />
      )}

      {/* Error state */}
      {isError && (
        <div className="lazy-image__error">
          <div className="lazy-image__error-icon">
            <svg
              width="24"
              height="24"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <circle cx="12" cy="12" r="10" />
              <line x1="12" y1="8" x2="12" y2="12" />
              <line x1="12" y1="16" x2="12.01" y2="16" />
            </svg>
          </div>
          <span className="lazy-image__error-text">Failed to load image</span>
        </div>
      )}

      {/* Progressive loading blur effect */}
      {isInView && !isLoaded && !isError && (
        <div className="lazy-image__progressive">
          <img
            src={createPlaceholder()}
            alt=""
            className="lazy-image__progressive-img"
            aria-hidden="true"
          />
        </div>
      )}
    </div>
  );
};

export default LazyImage;